"""Add read-only sourcing plan headers, approval metadata and payload snapshots."""
from alembic import op

revision = '0009_proc_plans'
down_revision = '0008_proc_inventory'
branch_labels = None
depends_on = None

SQL = "-- Plan headers and complete payload snapshots; authoritative writes stay in records.\nCREATE TABLE public.proc_plans (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK(source_revision>=1),\n    rfq_id varchar(64) NOT NULL,\n    rfq_revision integer NOT NULL CHECK(rfq_revision>=1),\n    creator_id varchar(64) NOT NULL CHECK(length(creator_id)>0),\n    status text NOT NULL CHECK(status IN ('pending','approved','rejected','superseded','execution_pending','executed')),\n    digest text NOT NULL CHECK(digest ~ '^[0-9a-f]{64}$'),\n    payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),\n    total numeric(16,2) NOT NULL CHECK(total>=0),\n    budget numeric(16,2) NOT NULL CHECK(budget>=0 AND total<=budget),\n    currency text NOT NULL CHECK(currency='AED'),\n    objective text NOT NULL CHECK(objective IN ('cost','delivery')),\n    approved_digest text CHECK(approved_digest ~ '^[0-9a-f]{64}$'),\n    approver_id varchar(64),\n    reason text,\n    expires_at timestamptz CHECK(isfinite(expires_at)),\n    intent_id varchar(64),\n    order_id varchar(64),\n    PRIMARY KEY(tenant,id),\n    FOREIGN KEY(tenant,rfq_id) REFERENCES public.proc_rfqs(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    CHECK(approver_id IS NULL OR approver_id<>creator_id),\n    CHECK(status NOT IN ('approved','rejected','execution_pending','executed') OR\n          (approver_id IS NOT NULL AND approved_digest IS NOT NULL AND approved_digest=digest\n           AND reason IS NOT NULL AND expires_at IS NOT NULL)),\n    CHECK(status NOT IN ('execution_pending','executed') OR intent_id IS NOT NULL),\n    CHECK(status<>'executed' OR order_id IS NOT NULL)\n);\nCREATE INDEX ix_proc_plans_rfq_status ON public.proc_plans(tenant,rfq_id,status);\nALTER TABLE public.proc_plans ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.proc_plans FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_scope ON public.proc_plans TO supplypilot_app\n    USING(tenant=NULLIF(current_setting('supplypilot.tenant',true),''))\n    WITH CHECK(tenant=NULLIF(current_setting('supplypilot.tenant',true),''));\nCREATE POLICY migration_owner ON public.proc_plans TO supplypilot_migrator USING(true) WITH CHECK(true);\nREVOKE ALL ON TABLE public.proc_plans FROM PUBLIC,supplypilot_app;\nGRANT SELECT ON TABLE public.proc_plans TO supplypilot_app;\n\nCREATE FUNCTION public.sync_procurement_plan()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp\nAS $$ DECLARE d jsonb; p jsonb; key text; amount numeric;\nBEGIN\n    IF TG_OP='UPDATE' AND (OLD.kind='plan' OR NEW.kind='plan') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Plan identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='plan' THEN DELETE FROM public.proc_plans WHERE tenant=OLD.tenant AND id=OLD.id; END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind<>'plan' THEN RETURN NEW; END IF;\n    d:=NEW.data::jsonb;p:=d->'payload';\n    IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR\n       jsonb_typeof(p->'allocations') IS DISTINCT FROM 'array' OR\n       jsonb_typeof(p->'stock_refs') IS DISTINCT FROM 'object' OR\n       jsonb_typeof(p->'shortages') IS DISTINCT FROM 'object' OR\n       (p->>'rfq_id') IS DISTINCT FROM (d->>'rfq_id') THEN\n        RAISE EXCEPTION 'Plan payload requires matching RFQ and structured sourcing facts' USING ERRCODE='23514';\n    END IF;\n    IF jsonb_typeof(p->'rfq_revision') IS DISTINCT FROM 'number' OR\n       (p->>'rfq_revision')::numeric<>trunc((p->>'rfq_revision')::numeric) THEN\n        RAISE EXCEPTION 'Plan RFQ revision must be an integer' USING ERRCODE='23514';\n    END IF;\n    FOREACH key IN ARRAY ARRAY['total','budget'] LOOP\n        amount:=(p->>key)::numeric;\n        IF amount::text IN ('NaN','Infinity','-Infinity') OR amount IS DISTINCT FROM round(amount,2) THEN\n            RAISE EXCEPTION 'Plan money must be finite with at most two decimal places' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    INSERT INTO public.proc_plans VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'rfq_id',\n        (p->>'rfq_revision')::integer,d->>'creator',d->>'status',d->>'digest',p,\n        (p->>'total')::numeric,(p->>'budget')::numeric,p->>'currency',p->>'objective',\n        d->>'approved_digest',d->>'approver',d->>'reason',(d->>'expires_at')::timestamptz,\n        d->>'intent_id',d->>'order_id')\n    ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n        rfq_id=EXCLUDED.rfq_id,rfq_revision=EXCLUDED.rfq_revision,creator_id=EXCLUDED.creator_id,\n        status=EXCLUDED.status,digest=EXCLUDED.digest,payload=EXCLUDED.payload,\n        total=EXCLUDED.total,budget=EXCLUDED.budget,currency=EXCLUDED.currency,objective=EXCLUDED.objective,\n        approved_digest=EXCLUDED.approved_digest,approver_id=EXCLUDED.approver_id,reason=EXCLUDED.reason,\n        expires_at=EXCLUDED.expires_at,intent_id=EXCLUDED.intent_id,order_id=EXCLUDED.order_id;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_plan() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_plan_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_plan();\nUPDATE public.records SET data=data WHERE kind='plan';\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Restore a reviewed backup; automatic plan projection removal is disabled.')
